mately 14.592 by 8.592 by 2.704 inches.","deterministic_checks":[{"check_type":"criterion-points","parameters":{"expected_points":1}}]},{"criterion_key":"part-d-criterion-2","points":1,"description":"Gives maximum volume approximately 339.013 cubic inches.","required_evidence":["Gives maximum volume approximately 339.013 cubic inches."],"accepted_variants":["Any mathematically equivalent expression, valid reasoning path, or appropriately rounded value supported by the student's setup."],"insufficient_responses":["A correct number without required setup, justification, interpretation, or units when that evidence is named in the criterion."],"contradictions":["Do not award the criterion when the response directly contradicts the required mathematical relationship or contextual meaning."],"minimum_fix":"Add or correct the evidence needed to establish: Gives maximum volume approximately 339.013 cubic inches.","deterministic_checks":[{"check_type":"criterion-points","parameters":{"expected_points":1}}]}]}],"scoring_contract":{"total_points":9,"part_count":4,"calculator_mode":"no-calculator","carry_forward_rule":"A later criterion may earn when the student's earlier arithmetic error is carried forward consistently and the later reasoning remains valid.","rounding_rule":"Accept exact values or values correctly rounded to the precision requested.","units_rule":"Units are required only when a criterion or prompt explicitly requests contextual units.","ambiguity_rule":"Escalate responses that use a valid but unlisted interpretation rather than forcing a score."},"development_cases":{"full_credit":"Provides all required setup, values, justifications, interpretations, and units.","partial_credit":"Shows a valid method for multiple criteria but omits or misstates at least one independently required piece of evidence.","no_credit":"Provides no relevant calculus relationship or only unsupported answers.","equivalent":"Uses algebraically equivalent forms or a different valid theore